vector<string> accept_events(const vector<string>& events) {
    unordered_set<string> seen;
    vector<string> accepted;
    for (const auto& event_id : events) {
        if (seen.count(event_id)) continue;
        accepted.push_back(event_id);
    }
    return accepted;
}

