class Cache:
    """Values expire at now + ttl. Expiry time is exclusive."""
    def __init__(self):
        self.items = {}

    def put(self, key, value, now, ttl):
        self.items[key] = (value, now + ttl)

    def get(self, key, now):
        if key not in self.items:
            return None
        value, expires = self.items[key]
        if now > expires:
            del self.items[key]
            return None
        return value

