#include <string>
#include <unordered_map>
#include <optional>
using namespace std;

class Cache {
    struct Entry { string value; long long expires; };
    unordered_map<string, Entry> items;
public:
    void put(const string& key, const string& value, long long now, long long ttl) {
        items[key] = {value, now + ttl};
    }
    optional<string> get(const string& key, long long now) {
        auto it = items.find(key);
        if (it == items.end()) return nullopt;
        if (now > it->second.expires) {
            items.erase(it);
            return nullopt;
        }
        return it->second.value;
    }
};

