def dependency_order(tasks, dependencies):
    """Each (before, after) pair uses known tasks. Return an order or reject cycles."""
    outgoing = {task: [] for task in tasks}
    degree = {task: 0 for task in tasks}
    for before, after in dependencies:
        outgoing[before].append(after)
        degree[after] += 1
    ready = deque(task for task in tasks if degree[task] == 0)
    order = []
    while ready:
        task = ready.popleft()
        order.append(task)
        for child in outgoing[task]:
            degree[child] -= 1
            if degree[child] == 0:
                ready.append(child)
    if len(order) != len(tasks):
        raise ValueError("cycle")
    return order

