#include <vector>
#include <queue>
#include <stdexcept>
using namespace std;

// Tasks are 0..count-1. Dependencies are valid (before, after) pairs.
vector<int> dependency_order(int count, const vector<pair<int,int>>& dependencies) {
    vector<vector<int>> outgoing(count);
    vector<int> degree(count, 0), order;
    for (auto [before, after] : dependencies) {
        outgoing[before].push_back(after);
        ++degree[after];
    }
    queue<int> ready;
    for (int task = 0; task < count; ++task)
        if (degree[task] == 0) ready.push(task);
    while (!ready.empty()) {
        int task = ready.front(); ready.pop();
        order.push_back(task);
        for (int child : outgoing[task])
            if (--degree[child] == 0) ready.push(child);
    }
    return order;
}

